    A recursive descent parser for JSON based on a finite state machine approach.
    It handles strings, numbers, booleans, null, arrays, and objects.
    """

    def parse_value():
        nonlocal index
        char = s[index]

        if char == '"':
            return parse_string()
        elif char.isdigit() or char == '-':
            return parse_number()
        elif char == 't':
            index += 4  # Skip "true"
            return True
        elif char == 'f':
            index += 5  # Skip "false"
            return False
        elif char == 'n':
            index += 4  # Skip "null"
            return None
        elif char == '[':
            return parse_array()
        elif char == '{':
            return parse_object()
        else:
            raise ValueError(f"Unexpected character: {char}")

    def parse_string():
        nonlocal index
        index += 1  # Skip initial quote
        start = index

        while index < len(s):
            char = s[index]
            if char == '"':
                value = s[start:index]
                index += 1  # Skip closing quote
                return value
            elif char == '\\':
                index += 1
                if s[index] in '"\\/bfnrt':
                    index += 1
                else:
                    raise ValueError(f"Invalid escape sequence at index {index}")
            else:
                index += 1

        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal index
        start = index
        while index < len(s) and (s[index].isdigit() or s[index] in '-+.'):
            index += 1
        number = s[start:index]
        if '.' in number:
            return float(number)
        return int(number)

    def parse_array():
        nonlocal index
        index += 1  # Skip opening bracket
        arr = []

        while index < len(s):
            char = s[index]
            if char == ']':
                index += 1  # Skip closing bracket
                return arr
            elif char == ',':
                index += 1  # Skip comma
                continue
            arr.append(parse_value())

        raise ValueError("Unterminated array")

    def parse_object():
        nonlocal index
