    def parse_null():
        nonlocal index
        if s[index:index + 4] == 'null':
            index += 4
            return None
        raise ValueError("Invalid literal for null")

    def parse_array():
        nonlocal index
        index += 1  # Skip opening bracket
        result = []
        skip_whitespace()
        if s[index] == ']':
            index += 1  # Empty array
            return result
        while True:
            result.append(parse_value())
            skip_whitespace()
            if s[index] == ']':
                index += 1
                return result
            elif s[index] == ',':
                index += 1
                skip_whitespace()
            else:
                raise ValueError("Expected ',' or ']' in array")

    def parse_object():
        nonlocal index
        index += 1  # Skip opening brace
        result = {}
        skip_whitespace()
        if s[index] == '}':
            index += 1  # Empty object
            return result
        while True:
            key = parse_string()
            skip_whitespace()
