            result[key] = parse_value()
            skip_whitespace()
            if s[index] == '}':
                index += 1
                return result
            elif s[index] == ',':
                index += 1
                skip_whitespace()
            else:
                raise ValueError("Expected ',' or '}' in object")

    return parse_value()

