                if s[i] == 'u':
                    hex_str = s[i + 1:i + 5]
                    string.append(chr(int(hex_str, 16)))
                    return ''.join(string), i + 5
                else:
                    string.append({
                        '"': '"', '\\': '\\', '/': '/',
                        'b': '\b', 'f': '\f', 'n': '\n', 
                        'r': '\r', 't': '\t'
                    }[s[i]])
                    escaped = False
            elif s[i] == '\\':
                escaped = True
            elif s[i] == '"':
