        elif s.startswith('true', position):
            position += 4
            return True
        elif s.startswith('false', position):
            position += 5
            return False
        elif s.startswith('null', position):
            position += 4
            return None
        else:
            raise ValueError(f"Unexpected character: {current_char}")

    def parse_object():
        nonlocal position
        obj = {}
